package tantei

import (
	"testing"
	"time"
)

// Values independently calculated using DateTimeOffset ticks in .NET, not
// generated by the implementation under test.
func TestDecodeDateTimeOffsetBinary(t *testing.T) {
	for _, tc := range []struct {
		encoded int64
		utc     string
	}{
		{1272537022464000000, "1970-01-01T00:00:00Z"},
		{1309279315048927562, "2026-11-07T07:44:15.1234Z"},
		{1309278415339267676, "2026-11-07T08:02:03.9876Z"},
		{0, "0001-01-01T00:00:00Z"},
		{6462216142847997952, "9999-12-31T23:59:59.9999Z"},
	} {
		t.Run(tc.utc, func(t *testing.T) {
			got, err := DecodeDateTimeOffsetBinary(tc.encoded)
			if err != nil {
				t.Fatal(err)
			}
			if got.Format(time.RFC3339Nano) != tc.utc {
				t.Fatalf("got %s, want %s", got.Format(time.RFC3339Nano), tc.utc)
			}
		})
	}
}

func TestDecodeDateTimeOffsetRejectsInvalidEncodings(t *testing.T) {
	for _, value := range []int64{-1, 1272537022464000000 | 900, 6462216142848000000, 840} {
		if _, err := DecodeDateTimeOffsetBinary(value); err == nil {
			t.Fatalf("accepted invalid encoding %d", value)
		}
	}
}
